// FindAPIKeyByID paginates the list endpoint until it finds a matching
// id. Returns nil (no error) if the key isn't found — the caller maps
// that to "removed externally, drop from state." This is the workaround
// for the missing GET /v1/api_keys/{id}; revisit when the gateway adds
// the singular endpoint (then this collapses to a one-shot GET).
//
// `gwclient.ApiKeyResponse` is the masked-shape DTO (no plaintext),
// matching the gateway's `/v1/api_keys` GET contract field-for-field.
func (c *Client) FindAPIKeyByID(ctx context.Context, id string) (*gwclient.ApiKeyResponse, error) {
	cursor := ""
	for {
		path := "/v1/api_keys?limit=100"
		if cursor != "" {
			path += "&cursor=" + cursor
		}
		var page gwclient.PageApiKeyResponse
		if err := c.do(ctx, "GET", path, nil, &page, ""); err != nil {
			return nil, err
		}
		for i := range page.Data {
			if page.Data[i].Id == id {
				return &page.Data[i], nil
			}
		}
		if !page.HasMore || page.NextCursor == nil {
			return nil, nil
		}
		cursor = *page.NextCursor
	}
}
